def _validate_trans_variables(variables, parser, lineno):
    for name, expr in variables.items():
        if not name.isidentifier():
            parser.fail(f"Invalid variable name '{name}' at line {lineno}. Python identifiers are required.")
        if name in ("gettext", "ngettext", "pgettext", "npgettext", "_"):
            parser.fail(f"Variable name '{name}' conflicts with translation function names at line {lineno}.")
        if isinstance(expr, nodes.Call):
            _validate_trans_expression(name, expr, parser, lineno)
        elif not isinstance(expr, (nodes.Const, nodes.Name, nodes.Call, nodes.Getattr, nodes.Filter, nodes.Test)):
            parser.fail(f"Invalid expression type '{expr}' for translation context at line {lineno}.")

def _validate_trans_expression(name, expr, parser, lineno):
    if isinstance(expr, nodes.Call):
        if not isinstance(expr.func, nodes.Name) or expr.func.name not in ("gettext", "ngettext", "pgettext", "npgettext", "_"):
            parser.fail(f"Invalid function call '{expr}' for translation context at line {lineno}.")
    elif not isinstance(expr, (nodes.Const, nodes.Name, nodes.Getattr, nodes.Filter, nodes.Test)):
        parser.fail(f"Invalid expression type '{expr}' for translation context at line {lineno}.")
